package it.gzanee.flightfinder.engine

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonNull
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import java.io.File

/** Cases generated by the Python portal (tools/golden_*.py) and the bundled catalog. */
object Fixtures {
    private val dir = File(System.getProperty("fixtures"))
    private val catalog = File(System.getProperty("catalog"))

    fun text(name: String) = File(dir, name).readText()
    fun json(name: String): JsonElement = Json.parseToJsonElement(text(name))
    fun file(name: String) = File(dir, name)

    fun installCatalog() {
        if (Airports.installed) return
        fun c(name: String) = File(catalog, name).readText()
        Airports.install(c("airports.json"), c("places.json"), c("routes.json"), c("airlines.json"), c("countries_it.json"))
    }
}

val json = Json { encodeDefaults = true; explicitNulls = true }

/**
 * JSON equality as Python and Kotlin write it: 30 equals 30.0, a missing key
 * equals null, and `ignore` keys are skipped at any depth.
 */
fun sameJson(a: JsonElement?, b: JsonElement?, ignore: Set<String> = emptySet(), path: String = "$", onlyExpectedKeys: Boolean = false): String? {
    val x = a ?: JsonNull
    val y = b ?: JsonNull
    if (x is JsonObject && y is JsonObject) {
        for (k in (if (onlyExpectedKeys) y.keys else x.keys + y.keys)) {
            if (k in ignore) continue
            sameJson(x[k], y[k], ignore, "$path.$k", onlyExpectedKeys)?.let { return it }
        }
        return null
    }
    if (x is JsonArray && y is JsonArray) {
        if (x.size != y.size) return "$path: length ${x.size} != ${y.size}"
        x.indices.forEach { i -> sameJson(x[i], y[i], ignore, "$path[$i]", onlyExpectedKeys)?.let { return it } }
        return null
    }
    if (x is JsonPrimitive && y is JsonPrimitive && x !is JsonNull && y !is JsonNull) {
        if (x.isString != y.isString) return "$path: $x != $y"
        if (!x.isString) {
            val dx = x.content.toDoubleOrNull()
            val dy = y.content.toDoubleOrNull()
            if (dx != null && dy != null) return if (dx == dy) null else "$path: $x != $y"
        }
        return if (x.content == y.content) null else "$path: $x != $y"
    }
    return if (x == y) null else "$path: $x != $y"
}

fun assertSameJson(expected: JsonElement?, actual: JsonElement?, ignore: Set<String> = emptySet(), label: String = "") {
    val diff = sameJson(actual, expected, ignore)
    if (diff != null) throw AssertionError("$label $diff")
}
